78	/// The HTTPS URL a `did:web` document is published at: `/.well-known/did.json`
79	/// on the host for a bare domain, or `did.json` under the path the further
80	/// segments of the identifier name (`did:web:host:a:b` is
81	/// `https://host/a/b/did.json`). A port is written percent-encoded in the host
82	/// segment (`example.com%3A8443`).
83	pub fn did_web_url(did: &str) -> Result<String, ResolveError> {
84	    let invalid = || ResolveError::InvalidDid(did.to_string());
85	    let id = did.strip_prefix("did:web:").ok_or_else(invalid)?;
86	    let mut segments = id.split(':');
87	    let host = percent_decode(segments.next().unwrap_or_default()).ok_or_else(invalid)?;
88	    if host.is_empty() || host.contains('/') {
89	        return Err(invalid());
90	    }
91	    let path: Vec<String> = segments.map(percent_decode).collect::<Option<_>>().ok_or_else(invalid)?;
92	    if path.iter().any(|s| s.is_empty() || s.contains('/')) {
93	        return Err(invalid());
94	    }
95	    let mut url = format!("https://{host}");
96	    if path.is_empty() {
97	        url.push_str("/.well-known");
98	    }
99	    for segment in &path {
100	        url.push('/');
101	        url.push_str(segment);
102	    }
103	    url.push_str("/did.json");
104	    Ok(url)
105	}
106	
107	fn percent_decode(segment: &str) -> Option<String> {
108	    let bytes = segment.as_bytes();
109	    let mut out = Vec::with_capacity(bytes.len());
110	    let mut i = 0;
111	    while i < bytes.len() {
112	        if bytes[i] == b'%' {
113	            let hex = std::str::from_utf8(bytes.get(i + 1..i + 3)?).ok()?;
114	            out.push(u8::from_str_radix(hex, 16).ok()?);
115	            i += 3;
116	        } else {
117	            out.push(bytes[i]);
118	            i += 1;
